package com.zoutiw.bibla.data

object PhilippiansData {
    val verses: List<Verse> = listOf(
        Verse(book = "Filipyen", chapter = 1, verseNumber = 1, text = "Se mwen menm Pòl ak Timote, de sèvitè Jezikri, k'ap ekri lèt sa a voye bay tout pèp Bondye nan lavil Filip la k'ap viv ansanm nan Jezikri. Lèt sa a se pou tout moun ki chèf nan legliz la ak pou tout dyak yo tou.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 2, text = "Nou mande Bondye, Papa nou, ansanm ak Jezikri, Seyè a, pou yo ban nou benediksyon ak kè poze.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 3, text = "Mwen di Bondye mwen an mèsi pou nou chak fwa lide m' frape sou nou.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 4, text = "Chak fwa m'ap lapriyè tou pou nou, mwen fè l' ak kè kontan,", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 5, text = "poutèt jan nou te ede m' gaye bon nouvèl la, depi premye jou a jouk koulye a.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 6, text = "Mwen sèten Bondye ki te konmanse bon travay sa a nan nou, li gen pou l' kontinye l' jouk li va fini l' nèt, lè jou Jezikri a va rive.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 7, text = "Se tou nòmal pou m' fè lide konsa sou nou, paske nou toujou nan lespri m', nou tout ki kanpe la avè m' nan tout favè Bondye fè m', kit lè mwen nan prizon tankou koulye a, kit lè mwen te lib pou m' defann bon nouvèl la, pou m' moutre se laverite li ye.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 8, text = "Mwen pran Bondye sèvi m' temwen, sa m'ap di nou la a se vre wi. Mwen renmen nou tout anpil anpil avèk renmen ki soti nan Jezikri.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 9, text = "Lè m'ap lapriyè Bondye, mwen mande l' pou nou gen plis renmen toujou, ak bonkou konesans pou nou ka rive konprann tout bagay,", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 10, text = "pou nou ka toujou chwazi sa ki pi bon. Konsa, n'a mennen yon lavi ki pwòp, yo p'ap jwenn anyen pou repwòche nou lè Kris la va vini.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 11, text = "Konsa, Jezikri va fè nou fè anpil bagay ki dwat epi ki bon, pou sa ka sèvi yon lwanj ak yon bèl bagay pou Bondye.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 12, text = "Frè m' yo, mwen vle nou konn sa byen: Tout bagay sa yo ki rive m' lan, yo pi fè travay predikasyon bon nouvèl la mache pase yo fè lòt bagay.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 13, text = "Se konsa, tout gad palè yo ansanm ak tout lòt moun yo konnen se paske m'ap sèvi Kris la kifè m' nan prizon.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 14, text = "Frè yo menm, bò pa yo, lè yo wè m' nan prizon an, pifò ladan yo vin gen plis konfyans toujou nan Seyè a. Sa ba yo plis kouraj koulye a pou fè konnen pawòl Bondye a san yo pa pè anyen.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 15, text = "Gen ladan yo k'ap fè konnen Kris la paske jalouzi moute yo nan tèt, yo ta renmen ban m' traka. Se vre. Men, gen lòt tou k'ap fè l' ak bon lide nan tèt yo.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 16, text = "Se renmen Bondye a k'ap pouse yo fè l', paske yo konnen se Bondye menm ki ban m' travay sa a pou m' ka defann bon nouvèl la.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 17, text = "Men, lòt yo ap fè konnen Kris la ak move lide dèyè tèt yo, y'ap fè l' pou lanbisyon pèsonèl pa yo. Y'ap fè l' pou chache m' kont. Yo konprann yo ka fè m' lapenn antan m' nan prizon an.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 18, text = "Men, sa pa fè m' anyen. Kit yo gen bon lide, kit yo gen move lide, tout jan se Kris la y'ap fè konnen. Epi sa fè kè m' kontan. M'ap pi kontan toujou,", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 19, text = "paske mwen konnen tout bagay sa yo pral vire anbyen pou mwen, gremesi lapriyè n'ap fè pou mwen ak lasistans Lespri Jezikri a ap ban mwen.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 20, text = "Paske, mwen ta renmen pou m' pa soti wont nan anyen. Se la tout espwa m' pou m' ka pale ak kouraj, pou jòdi a tankou anvan lèzòm ka wè pouvwa Kris la nan mwen, kit mwen vivan, kit mwen mouri.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 21, text = "Paske pou mwen, lavi se Kris la. Se poutèt sa lanmò se yon gany pou mwen.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 22, text = "Men, si antan m'ap viv sou tè a toujou, mwen ka fè kèk travay ankò pou Seyè a, nan ka sa a, mwen pa konn sa m' pito.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 23, text = "Mwen ta renmen fè tou de: Mwen ta renmen mouri pou m' ta avè Kris la. Sa ta pi bon anpil pou mwen.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 24, text = "Men, li ta pi bon pou nou pou m' rete viv sou latè.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 25, text = "Mwen sèten se sa k'ap rive menm. Se poutèt sa, mwen konnen mwen gen pou m' rete, pou m' ka viv ansanm ak nou, pou m' ede nou grandi, pou m' ka fè nou kontan nan konfyans nou gen nan Bondye.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 26, text = "Konsa, lè m'a tounen bò kote nou, m'a ban nou yon bèl okazyon pou nou kontan nan lavi n'ap mennen ansanm nan Kris la.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 27, text = "Sèl bagay ki konsekan se pou nou viv yon jan ki konfòm ak bon nouvèl Kris la. Konsa, mwen ta mèt rive vin wè nou, mwen ta mèt pa kapab, se pou m' tande jan n'ap kenbe fèm, jan n'ap viv ansanm yonn ak lòt. Se pou m' tande jan n'ap mennen batay la ansanm pou defann konfyans bon nouvèl la fè nou gen nan Bondye.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 28, text = "Pa kite okenn lènmi kraponnen nou. Se pou tout bagay sa yo sèvi tankou yon prèv pou fè lènmi yo wè se pèdi y'ap pèdi tèt yo. Men, pou nou menm, yo fè wè se delivre n'ap delivre. Sa se travay Bondye.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 29, text = "Paske nou menm k'ap sèvi Kris la, Bondye ban nou favè sa a, non sèlman pou nou gen konfyans nan li, men pou nou ka soufri avè li tou.", bookId = 50),
        Verse(book = "Filipyen", chapter = 1, verseNumber = 30, text = "Batay n'ap mennen an, se menm batay la m'ap mennen tou. Se menm batay nou te wè m'ap mennen nan tan lontan an. Se li menm m'ap mennen jouk koulye a, jan nou konnen an.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 1, text = "Konsa, si se nan Kris la nou jwenn fòs kouraj nou tout bon vre, si se renmen li renmen nou an ki ban nou ankourajman tout bon vre, si Sentespri l' rete nan kè nou tout bon vre, si tout bon vre nou yonn renmen lòt, si nou sansib yonn pou lòt,", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 2, text = "enben, men sa m'ap mande nou: Fè kè m' kontan nèt. Se pou nou viv byen yonn ak lòt, se pou nou yonn renmen lòt menm jan an, pou nou tout gen yon sèl lide nan tèt nou ak yon sèl santiman nan kè nou.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 3, text = "Pa fè anyen nan lide pou fè tèt nou pase pou pi bon, ni pou fè lwanj tèt nou. Men, soumèt nou devan Bondye. Mete nan tèt nou lòt yo pi bon pase nou.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 4, text = "Piga pesonn chache enterè pa l' ase. Se pou l' chache sa ki bon pou lòt yo tou.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 5, text = "Se pou nou yonn gen pou lòt menm santiman ki te nan Jezi, Kris la.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 6, text = "Sa Bondye ye a, se sa l' te toujou ye. Men, li pa t' janm konsidere sa tankou yon avantaj pou l' te chache kenbe ak tout fòs.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 7, text = "Okontrè, se li menm pou tèt pa l' ki chwazi mete sa sou kote. Li te pito tounen yon domestik. Li pran fòm yon moun, li vin tankou tout moun.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 8, text = "Li rabese tèt li. Tankou yon moun, li soumèt devan Bondye. Li obeyi Bondye jouk li rive asepte mouri, wi jouk li asepte mouri sou kwa a.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 9, text = "Se poutèt sa, Bondye leve l' mete chita kote ki pi wo a. Li ba li yon non ki pi gran pase tout lòt non.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 10, text = "Konsa, tou sa ki nan syèl la, tou sa ki sou tè a ak anba tè a, yo tout va mete jenou yo atè devan Jezi pa respè pou non Bondye te ba li a.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 11, text = "Tout moun va rekonèt Jezikri se Seyè a. Sa va sèvi yon lwanj pou Bondye Papa a.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 12, text = "Se konsa, zanmi m' yo, nou tout nou te toujou obeysan lè m' te la avèk nou. Koulye a m' pa la ankò, se lè sa a pou n' pi obeyisan: toujou fè jefò pou nou ka fin sove nèt, avèk krentif pou Bondye, avèk soumisyon devan li.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 13, text = "Paske, se Bondye menm k'ap travay tout tan nan kè nou. Se li ki ban nou anvi fè sa ki pou fè l' plezi ansanm ak fòs pou nou ka fè l' vre.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 14, text = "Nan tou sa n'ap fè, pa plenyen, pa diskite,", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 15, text = "pou yo pa jwenn anyen pou yo repwoche nou, pou nou ka fè sa ki byen tankou bon pitit Bondye, antan n'ap viv nan mitan bann moun malonèt ak bann mechan sa yo ki sou latè. Se pou nou klere nan mitan yo tankou zetwal nan syèl la,", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 16, text = "lè n'ap ba yo mesaj ki bay lavi a. Konsa, n'a fè kè m' kontan lè jou Kris la va rive. Paske, m'a konnen mwen pa t' fatige kò m' pou gremesi, mwen pa t' travay mal.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 17, text = "Menm si mwen dwe ofri lavi m', menm si san m' ta gen pou l' koule pou wouze ofrann n'ap fè pou Bondye paske nou gen konfyans nan li a, m'ap kontan anpil, epi m'ap fè kè nou tout kontan ansanm avè mwen.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 18, text = "Konsa, nou menm tou, se pou nou kontan, se pou nou fè kè m' kontan ansanm avè nou tou.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 19, text = "Si se volonte Seyè Jezi, mwen fè lide voye Timote kote nou anvan lontan, pou lè m' pran nouvèl nou sa ka ban m' ankourajman.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 20, text = "Timote se sèl moun ki gen menm lide avè m', ki vle wè byen nou. Mwen pa gen lòt.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 21, text = "Tout lòt yo, se zafè pa yo ase y'ap regle, yo p'ap defann kòz Kris la.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 22, text = "Nou menm tou nou konnen jan Timote se yon nèg serye. Tankou papa ak pitit nou travay ansanm pou bon nouvèl la.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 23, text = "Mwen fè lide voye l' kote nou lè m'a fin wè ki jan sa ap pase pou mwen.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 24, text = "Men, mwen gen konfyans sa a nan Bondye: m'a ka vin wè nou anvan lontan.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 25, text = "Konsa tou, nou chonje Epafwodit, frè nou an, ki te travay ansanm avè m', ki te la avè m' nan tout batay. Se nou menm ki te voye l' vin ban m' konkou. Enben, mwen wè se nesesè pou m' voye l' tounen ban nou.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 26, text = "Se pa ti anvi li anvi wè nou. Sa te travay tèt li anpil dèske nou te vin konnen jan l' te malad.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 27, text = "Li te malad anpil, se vre. Li manke mouri. Men, Bondye te gen pitye pou li. Pa pou li sèlman, men pou mwen menm tou, pou sa pa t' ban mwen plis lapenn ankò.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 28, text = "Se poutèt sa mwen pi anvi voye li bò kote nou pou nou ka kontan lè n'a wè l' ankò, epi pou m' ka gen mwens lapenn.", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 29, text = "Konsa, resevwa l' ak kè kontan tankou yon frè nan Seyè a. Se pou nou gen anpil respè pou moun ki tankou Epafwodit,", bookId = 50),
        Verse(book = "Filipyen", chapter = 2, verseNumber = 30, text = "paske li te prèt pou mouri pou travay Kris la, li riske lavi l' pou l' te ka ban mwen konkou nou menm nou pa t' kapab ban mwen.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 1, text = "Koulye a, frè m' yo, fè kè nou kontan nan Seyè a. Pou mwen, sa pa fè m' anyen pou m' repete sa m' te voye di nou deja. Men, se nan avantaj nou.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 2, text = "Veye kò nou ak moun k'ap plede fè sa ki mal yo. Veye kò nou ak bann chen sa yo ki vle fè yo sikonsi nou.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 3, text = "Si gen moun ki sikonsi tout bon, se pa yo, se nou menm. Paske nou menm, n'ap sèvi Bondye ak Lespri Bondye a, nou kontan dèske n'ap viv ansanm ak Jezikri. Nou pa mete konfyans nou nan sa lèzòm ap fè.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 4, text = "Mwen ta ka mete konfyans mwen nan bagay konsa tou, si m' te vle. Si gen moun ki kwè yo ka mete konfyans yo nan sa lèzòm ap fè, mwen pi ka fè l' pase yo.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 5, text = "Mwen te gen wit jou depi m' te fèt lè yo sikonsi mwen. Mwen se yon moun Izrayèl natif natal, nan branch fanmi Benjamen, pitit pitit Ebè san (100) pou san (100). Sou keksyon lalwa Moyiz la menm, se pa pale: se farizyen mwen te ye.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 6, text = "Mwen te sitèlman yon patizan fanatik lalwa a, mwen te menm rive pèsekite legliz la. Si yon moun te ka bon paske li fè sa lalwa a mande, enben mwen te bon nèt ale.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 7, text = "Men, si yon lè mwen te konsidere tout bagay sa yo tankou yon garanti, koulye a yo pa vo anyen pou mwen, akòz Kris la.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 8, text = "Men, se pa sa sèlman. Se tout bagay menm ki pa vo anyen pou mwen, lè m' konpare yo ak gwo avantaj mwen genyen lè m' konnen Jezikri tankou Seyè mwen. Poutèt li, mwen voye tout bagay jete, mwen gade yo tankou fatra pou m' sa gen Kris la,", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 9, text = "pou m' ka viv ansanm avè l' nèt ale. Konsa, mwen pa gen pretansyon mwen bon paske mwen fè sa lalwa a mande. Men, Bondye fè m' gras paske mwen mete konfyans mwen nan Kris la. Wi, Bondye fè tout moun ki mete konfyans yo nan li gras.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 10, text = "Se yon sèl bagay mwen bezwen: se konnen pou m' konnen Kris la, pou m' santi nan mwen pouvwa ki te fè l' leve soti vivan nan lanmò a, pou m' soufri ansanm avè l' nan soufrans li yo, pou m' rive mouri tankou li tou,", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 11, text = "avèk espwa, mwen menm tou m'a gen pou m' leve soti vivan nan lanmò.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 12, text = "Mwen pa gen pretansyon mwen rive deja kote m' prale a, ni mwen poko fin bon nèt. Men, m'ap kouri sou kous mwen pou m' wè si m' ka mete men sou kote m' dwe rive a, paske Jezikri pou tèt pa l' fin mete men sou mwen deja.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 13, text = "Se vre wi, frè m' yo. Mwen pa kwè mwen deja mete men m' sou kote m' dwe rive a. Men, mwen gen yon sèl bagay pou m' fè, se pou m' bliye tou sa ki dèyè m' pou m' fè jefò pou m' mete men m' sou sa ki devan m' lan.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 14, text = "Konsa, m'ap kouri dwat devan m' sou mak kote m' prale a, pou m' ka jwenn rekonpans Bondye rele m' vin resevwa nan syèl la, gremesi Jezikri.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 15, text = "Nou tout ki byen grandi nan lafwa, se menm lide sa a pou n' gen nan tèt nou tou. Men, si gen moun pami nou ki gen lòt lide sou kèk pwen, Bondye va fè yo wè pi klè sou sa.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 16, text = "Nenpòt jan sa ye, ann mache toujou jan n' te konmanse a.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 17, text = "Nou tout frè m' yo, pran egzanp sou mwen. Kenbe je nou fiske sou moun k'ap swiv egzanp mwen te bay la.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 18, text = "Paske, gen anpil moun k'ap viv tankou moun ki pa vle tande pale jan Kris la mouri sou kwa a. Mwen te deja di nou sa, koulye a m'ap di nou sa ankò ak dlo nan je mwen:", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 19, text = "Moun sa yo ap rive fin detwi tèt yo. Se vant yo ki bondye yo. Yo pran plezi yo nan bagay ki pou ta fè yo wont pito. Se bagay lemonn ase ki nan tèt yo.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 20, text = "Men nou menm, nou se sitwayen peyi ki nan syèl la. Se tann n'ap tann Delivrans nou, Jezikri, Seyè a, ki gen pou desann sot nan syèl la.", bookId = 50),
        Verse(book = "Filipyen", chapter = 3, verseNumber = 21, text = "Se li menm k'ap pran pouvwa li genyen pou soumèt tout bagay anba men l' lan, l'ap chanje vye kò tou fèb nou yo pou l' fè yo tounen tankou kò pa l' la ki gen bèl pouvwa.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 1, text = "Se pou sa, frè m' yo ak zanmi m' yo, nou menm mwen anvi wè anpil la, nou menm ki fè kè m' kontan an, nou menm ki yon lwanj pou mwen an, se konsa pou nou kenbe fèm nan lavi n'ap mennen ansanm nan Seyè a.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 2, text = "M'ap ekri de ti mo pou Evodi ak Sentich: Tanpri souple, mete nou dakò tankou de sè k'ap viv ansanm nan Seyè a.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 3, text = "Ou menm tou k'ap travay ansanm avè m', mwen mande ou pou ou ede yo, paske de medam sa yo te travay di pou fè konnen bon nouvèl la ansanm ak Kleman ak tout lòt moun ki te travay ansanm avè mwen yo. Yo tout gen non yo ekri nan Liv Bondye a ki gen non moun ki gen lavi a.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 4, text = "Se pou nou toujou kontan nan lavi n'ap mennen ansanm nan Seyè a. M'ap repete l' ankò: Fè kè nou kontan anpil.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 5, text = "Se pou tout moun konnen nou se moun ki gen bon kè. Seyè a ap vini anvan lontan.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 6, text = "Pa bay kò nou traka pou anyen. Men, nan tout sikonstans mande Bondye tou sa nou bezwen nan lapriyè. Toujou chonje di l' mèsi tou lè n'ap lapriyè.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 7, text = "Konsa, Bondye va ban nou kè poze nan jan pa l', bagay lèzòm pa ka konprann; la kenbe kè nou ak lespri nou fèm nan Jezikri.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 8, text = "Pou fini, frè m' yo, mete lide nou sou bagay ki bon, ki merite lwanj: bagay ki vre, ki kòrèk, ki dwat, ki bèl, ki p'ap fè nou wont.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 9, text = "Fè tou sa mwen te moutre nou, ni sa nou te resevwa nan menm m', ni sa nou te tande m' di ak tou sa nou te wè m' fè. Konsa, Bondye k'ap bay kè poze a va toujou la avè nou.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 10, text = "Mwen pa t' manke kontan nan lavi m'ap mennen ansanm ak Seyè a, paske nou vin fè m' wè ankò jan nou pran ka mwen. Sa pa vle di nou te lage m' non. Men, nou pa t' ankò jwenn okazyon fè m' wè jan nou fèb pou mwen.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 11, text = "Si nou wè m'ap pale konsa, se pa paske koulye a mwen nan nesesite. Paske nan lavi, m' aprann kontante tèt mwen ak sa m' genyen.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 12, text = "Mwen konnen sa ki rele viv nan mizè, mwen konnen sa ki rele viv nan richès. Kit mwen pa gen ase, kit mwen gen plis pase sa m' bezwen, nan tout sikonstans m' aprann kontante tèt mwen toupatou ak sa mwen genyen.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 13, text = "Nenpòt sitiyasyon ki parèt devan mwen, m'ap degaje m', gremesi Kris la ki ban mwen fòs kouraj.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 14, text = "Malgre sa, nou byen fèt ede m' nan traka m' yo.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 15, text = "Nou menm, moun lavil Filip, nou byen konnen sa m' pral di nou la a. Lè mwen kite peyi Masedwan, lè yo te fenk konmanse ap pibliye bon nouvèl la, se nou menm sèl legliz ki te ede mwen. Se nou menm sèl ki te separe sa nou genyen avè m' pou sa m' te fè pou nou.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 16, text = "Lè m' te lavil Tesalonik, an de fwa nou voye sa m' te bezwen ban mwen.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 17, text = "Se pa dèyè kado mwen ye. Men, mwen ta renmen Bondye mete sou sa nou gen deja.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 18, text = "Wi, mwen resevwa tou sa nou te voye ban mwen, pou di vre, sa depase sa m' te bezwen. Koulye a, avèk Epafwodit ki pote kado nou yo, mwen gen tou sa m' bezwen. Kado nou yo se tankou yon ofrann ki santi bon, yon ofrann bèt Bondye ap asepte paske sa fè l' plezi.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 19, text = "Bondye ki rich anpil la va ban nou tou sa nou bezwen nan Jezikri.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 20, text = "Tout lwanj lan se pou Bondye, Papa nou, pou tout tan. Amèn.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 21, text = "Bonjou pou pèp Bondye a k'ap viv ansanm nan Jezikri. Tout frè ki la avè m' yo voye bonjou pou nou.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 22, text = "Tout pèp Bondye a ki isit la, espesyalman sa ki nan palè Seza a, voye bonjou pou nou.", bookId = 50),
        Verse(book = "Filipyen", chapter = 4, verseNumber = 23, text = "Se pou benediksyon Jezikri, Seyè a, toujou avè nou.", bookId = 50)
    )
